window.ScripturaLexicons.BDAG_PART_0355 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-01\" data-source=\"BDAG\" data-search=\"τεκεῖν remissão ver τίκτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκεῖν</td><td>remissão</td><td>ver τίκτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-02\" data-source=\"BDAG\" data-search=\"τεκμήριον, ου, τό substantivo neutro prova; demonstração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκμήριον, ου, τό</td><td>substantivo neutro</td><td>prova; demonstração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-03\" data-source=\"BDAG\" data-search=\"τέκνημα, ατος, τό substantivo neutro prole; descendência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέκνημα, ατος, τό</td><td>substantivo neutro</td><td>prole; descendência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-04\" data-source=\"BDAG\" data-search=\"τεκνίον, ου, τό substantivo neutro criança; filhinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκνίον, ου, τό</td><td>substantivo neutro</td><td>criança; filhinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-05\" data-source=\"BDAG\" data-search=\"τεκνογονέω verbo dar à luz; gerar filhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκνογονέω</td><td>verbo</td><td>dar à luz; gerar filhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-06\" data-source=\"BDAG\" data-search=\"τεκνογονία, ας, ἡ substantivo feminino ato de dar à luz filhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκνογονία, ας, ἡ</td><td>substantivo feminino</td><td>ato de dar à luz filhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-07\" data-source=\"BDAG\" data-search=\"τέκνον, ου, τό substantivo neutro filho; descendente; criança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέκνον, ου, τό</td><td>substantivo neutro</td><td>filho; descendente; criança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-08\" data-source=\"BDAG\" data-search=\"τεκνοτροφέω verbo criar filhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκνοτροφέω</td><td>verbo</td><td>criar filhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-09\" data-source=\"BDAG\" data-search=\"τεκνόω verbo gerar; dar à luz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεκνόω</td><td>verbo</td><td>gerar; dar à luz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-10\" data-source=\"BDAG\" data-search=\"τέκτων, ονος, ὁ substantivo masculino construtor; carpinteiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέκτων, ονος, ὁ</td><td>substantivo masculino</td><td>construtor; carpinteiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-11\" data-source=\"BDAG\" data-search=\"τέλειος, α, ον adjetivo perfeito; completo; maduro; iniciado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέλειος, α, ον</td><td>adjetivo</td><td>perfeito; completo; maduro; iniciado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-12\" data-source=\"BDAG\" data-search=\"τελειότης, ητος, ἡ substantivo feminino perfeição; plenitude BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελειότης, ητος, ἡ</td><td>substantivo feminino</td><td>perfeição; plenitude</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-13\" data-source=\"BDAG\" data-search=\"τελειόω verbo completar; aperfeiçoar; consagrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελειόω</td><td>verbo</td><td>completar; aperfeiçoar; consagrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-14\" data-source=\"BDAG\" data-search=\"τελείως advérbio plenamente; perfeitamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελείως</td><td>advérbio</td><td>plenamente; perfeitamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-15\" data-source=\"BDAG\" data-search=\"τελείωσις, εως, ἡ substantivo feminino perfeição; cumprimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελείωσις, εως, ἡ</td><td>substantivo feminino</td><td>perfeição; cumprimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-16\" data-source=\"BDAG\" data-search=\"τελειωτής, οῦ, ὁ substantivo masculino consumador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελειωτής, οῦ, ὁ</td><td>substantivo masculino</td><td>consumador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-17\" data-source=\"BDAG\" data-search=\"τέλεον advérbio plenamente; no fim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέλεον</td><td>advérbio</td><td>plenamente; no fim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-18\" data-source=\"BDAG\" data-search=\"τελεσφορέω verbo produzir fruto até a maturidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελεσφορέω</td><td>verbo</td><td>produzir fruto até a maturidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-19\" data-source=\"BDAG\" data-search=\"τελευταῖος, α, ον adjetivo último; final BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελευταῖος, α, ον</td><td>adjetivo</td><td>último; final</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0355-20\" data-source=\"BDAG\" data-search=\"τελευτάω verbo chegar ao fim; morrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελευτάω</td><td>verbo</td><td>chegar ao fim; morrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0355-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκεῖν</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκεῖν</span> v. <span class=\"greek\">τίκτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκμήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκμήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aeschyl., Hdt., Thu.+) aquilo que faz com que algo seja conhecido de maneira convincente e decisiva, prova (prova demonstrativa: Aristot., An. Pr. 70b, 2; Rh. 1357b 4; 1402b 19; Diod S 17, 51, 3 <span class=\"greek\">τεκμήρια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">γενέσεως</span>; SIG 867, 37 <span class=\"greek\">μέγιστον</span> <span class=\"greek\">τεκμήριον</span> com ref. a Ártemis; 685, 84; PGiss 39, 9) <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">τεκμηρίοις</span> mediante muitas provas convincentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a> (DMealand, ZNW 80, ’89, 134f [refs. helen.]; cf. Jos., Ant. 5, 39 <span class=\"greek\">διὰ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">τεκμηρίων</span>.—<span class=\"greek\">τεκ</span>. empregado com <span class=\"greek\">παραστῆσαι</span> Jos., Ant. 17, 128. Cf. Libanius, Or. 18, 13 <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">βασιλικὸν</span> <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλοις</span> <span class=\"greek\">τεκμηρίοις</span> <span class=\"greek\">ἐμηνύετο</span>=sua natureza régia era atestada por muitos sinais excepcionais).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκνημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέκνημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (hapax leg. em lugar de <span class=\"greek\">γέννημα</span>) prole, descendência <span class=\"greek\">τεκνήματα</span> <span class=\"greek\">ἐχιδνῶν</span> geração de víboras AcPlCor 2:38.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνίον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκνίον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Epict. 3, 22, 78; Anth. Pal.; PFlor 365, 15 [III d.C.]; POxy 1766, 14; TestJob, ApcMos) dim. de <span class=\"greek\">τέκνον</span>; criança (pequena), voc. pl. <span class=\"greek\">τεκνία</span>; em nossa lit. somente no voc. pl., empregado por Jesus ao dirigir-se familiar e afetuosamente a seus discípulos, ou por um apóstolo ou mestre cristão a seus filhos espirituais <span class=\"greek\">τεκνία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:12</a>, 28; 3:7, 18; 4:4; 5:21. <span class=\"greek\">τεκνία</span> <span class=\"greek\">μου</span> (TestReub 1:3; TestJob 5:1 al.; ApcMos 5:30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a> v.l.; 1J 2:1.—DELG s.v. <span class=\"greek\">τίκτω</span> C. Frisk s.v. <span class=\"greek\">τέκνον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνογονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκνογονέω</span> (v. artigo seguinte; Philippus Epigr. [I d.C.]: Anth. Pal. 9, 22, 4 [de um animal]) dar à luz/gerar filhos (Appian., Basil. 1a §5; Achmes 63, 10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:14</a>; Dg 5:6 (indicando uma prática normal entre os cristãos e em contraste com o costume do infanticídio; v. <span class=\"greek\">ῥίπτω</span> 1).—Cf. DELG s.v. <span class=\"greek\">γίγνομαι</span>; Frisk s.v. <span class=\"greek\">γονή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνογονία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκνογονία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (v. artigo precedente; Hippocr., Ep. 17, 21; Aristot., HA 7, 1, 8, 582a, 28; Stoic. III 158, 5; Galen: CMG V/9, 1 p. 27, 12; Cat. Cod. Astr. IX/1 p. 181, 17) o ato de dar à luz filhos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:15</a> (RFalconer, JBL 60, ’41, 375–79; SPorter, JSNT 49, ’93, 87–102; NDemand, Birth, Death, and Motherhood in Classical Greece ’94).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκνον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέκνον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">τίκτω</span> ‘gerar, dar à luz’; Hom.+ ‘criança’)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> descendente de pais humanos, filho</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> sem ref. ao sexo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21a</a> (sobre a completa dissolução dos vínculos familiares v. Lucian, Cal. 1; GrBar 4:17; ApcEsdr 3:14 p. 27, 23 Tdf.; Just., A I, 27, 3f; Orig., C. Cels. 6, 43, 25 [filhos de Jó]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:12a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:4</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:11</a>; 10:21b; 18:25; 19:29; 22:24 (=<span class=\"greek\">σπέρμα</span>, cf. Dt 25:5f, mas <span class=\"greek\">σπ</span>. e <span class=\"greek\">τ</span>. são contrapostos Ro 9:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:12b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a>; 14:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:14</a> (sobre o batismo de crianças v. HWood, EncRelEth II 392ff; JLeipoldt, D. urchr. Taufe 1928, 73–78; AOepke, LIhmels Festschr. 1928, 84–100, ZNW 29, 1930, 81–111 [contra ele HWindisch, ZNW 28, 1929, 118–42]; JJeremias, Hat d. Urkirche d. Kindertaufe geübt? ’38; 2ª ed. ’49; Die Kindert. in d. ersten 4 Jhdtn. ’58; retomado em D. Anfänge d. Kindert. ’62; v. também ZNW 40, ’42, 243–45. KAl-and, D. Saülingst. im NT u. in d. alten Kirche ’62, 2ª ed. ’63; Die Stellung d. Kinder in d. frühe christl. Gemeinden, und ihre Taufe ’67. KBarth, Z. kirchl. Lehre v. d. Taufe2 ’43; D. Taufe als Begründung d. christlichen Lebens in Kirchliche Dogmatik IV, 4, ’67; para discussão das opiniões de Barth, v. EJüngel, K. Barths Lehre v. d. Taufe ’68; KViering (ed.), Zu K. Barth’s Lehre v. d. Taufe ’71; K. Aland, Taufe u. Kindertaufe ’71; HHubert, D. Streit um d. Kindertaufe, ’72. FFr̓vig, TTK 11, ’40, 124–31; EMolland, NorTT 43, ’42, 1–23; F-JLeenhardt, Le Baptème chrétien ’46; OCullmann, D. Tauflehre d. NT ’48; P-HMenoud, Verbum Caro 2, ’48, 15–26; HSchlier, TLZ 72, ’47, 321–26; GFleming, Baptism in the NT ’49; GBeasley-Murray, Baptism in the New Testament ’62; WKümmel, TRu 18, ’50, 32–47; GDelling, D. Taufe im NT ’63; EDinkler, Die Taufaussagen d. NT ’71 [em: KViering, v. acima, 60–153]; JDidier, Le baptême des enfants ’59; HKraft, Texte z. Gesch. d. Taufe bes. d. Kindert. i. d. alten Kirche, Kl. T. n.º 174, 2ª ed. ’69); 2 Cor 12:14ab (símile); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:7</a> (símile), 11 (símile); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:4</a>, 12; 5:4 al. Na tábua dos deveres domésticos (v. MDibelius Hdb. exc. após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:1</a>; KWeidinger, Die Haustafeln 1928) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:1</a> (<span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> voc.), 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:20</a> (<span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. voc.), 21. No caso de <span class=\"greek\">φονεῖς</span> <span class=\"greek\">τέκνων</span> B 20:2; D 5:2, o que se segue mostra que se tem em vista o assassinato dos próprios filhos.—O feto ainda não nascido também é chamado <span class=\"greek\">τέκνον</span> B 19:5; D 2:2 (como <span class=\"greek\">παιδίον</span>: Hippocr., <span class=\"greek\">π</span>. <span class=\"greek\">σαρκ</span>. 6 vol. VIII 592 L. Sobre a atitude de Jesus para com as crianças, cf. JKalogerakos, Aristoteles’ Bild von der Frau: <span class=\"greek\">ΠΛΑΤΩΝ</span> 46, ’94, 159–83, esp. p. 174 e notas [cf. Aristot., EN 1161b].).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> O sexo da criança pode ser esclarecido pelo contexto, filho (Herodian 7, 10, 7; PGen 74, 1ff; PAmh 136, 1f; POxy 930, 18; Jos., Ant. 14, 196; Just., D. 56, 5; 134, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:28a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:22</a> (símile); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:5</a>; GJs 22;3. O voc. <span class=\"greek\">τέκνον</span> como forma afetuosa de dirigir-se a um filho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:28b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:48</a>; 15:31. Em sentido mais geral, o pl. é empregado para</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> descendentes de um antepassado comum, descendentes, posteridade <span class=\"greek\">Ῥαχὴλ</span> <span class=\"greek\">κλαίουσα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jer 38:15).—27:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a>; 13:33. Um homem rico é interpelado por seu antepassado Abraão como <span class=\"greek\">τέκνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span> os descendentes físicos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:8a</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> pessoa querida de outra, mas sem parentesco genético e sem distinção de idade, filho</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> no voc., geralmente como forma familiar de tratamento, meu filho, minha criança (Herodian 1, 6, 4; ParJer 5:30; Achilles Tat. 8, 4, 3. Dirigido a pessoas plenamente adultas, Vi. Aesopi G 60 P., onde um camponês se dirige a Esopo desse modo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:5</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de um filho espiritual em relação a mestre, apóstolo ou professor (PGM 4, 475.—Eunap. p. 70 o sofista aplica este termo a seus alunos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:2</a>; Phlm 10. <span class=\"greek\">τέκνον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>. <span class=\"greek\">τέκ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:2</a>. <span class=\"greek\">τέκ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κοινὴν</span> <span class=\"greek\">πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:4</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:13</a>; 3J 4. Em interpelação direta (voc.): sing. (sobre a interpelação direta no sing. cf. Sir 2:1 e frequentemente; Herm. Wr. 13, 2ab; PGM 13, 226; 233; 742; 755.—V. também Norden, Agn. Th. 290f; Boll 138f): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:1</a>; D 3:1, 3–6; 4:1. Pl.: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:24</a>; B 15:4.—1 Cl 22:1 entende os <span class=\"greek\">τέκνα</span> de Ps 33:12 como palavra de Cristo aos cristãos. Cf. B 9:3. A interpelação em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a> destina-se metaforicamente aos filhos pelos quais Paulo sofre novamente as dores do parto.—Os adeptos de falsos mestres também são chamados seus <span class=\"greek\">τέκνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:23</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> dos membros de uma congregação 2J 1; 4; 13. Em Hermas, a venerável senhora, que personifica as comunidades cristãs, dirige-se aos crentes como <span class=\"greek\">τέκνα</span> Hv 3, 9, 1. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:31</a> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">παιδίσκης</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλευθέρας</span> apresenta uma imagem dramática = ‘não pertencemos a uma comunidade dependente das normas do Sinai, mas a uma que adere às promessas feitas a Abraão’.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> pessoa que possui as características de outro ser, filho</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> daqueles que manifestam as virtudes de veneráveis personagens da antiguidade: filhos de Abraão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:7</a>. As verdadeiras mulheres cristãs são filhas de Sara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:6</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> daqueles que manifestam características de entidades transcendentes: os crentes são (<span class=\"greek\">τὰ</span>) <span class=\"greek\">τέκνα</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θεοῦ</span> (cf. Is 63:8; Wsd 16:21; SibOr 5, 202; Just., D. 123, 9; 124, 1. Sobre o assunto v. HHoltzmann, Ntl. Theologie I2 1911, 54; Bousset, Rel.3 377f; ADieterich, Mithrasliturgie 1903, 141ff; Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:12</a>; WGrundmann, Die Gotteskindschaft in d. Gesch. Jesu u. ihre relgesch. Voraussetzungen ’38; WTwisselmann, D. Gotteskindsch. der Christen nach dem NT ’39; SLegasse, Jésus et L’enfant [synopt.], ’69), em Paulo como os que foram adotados por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:16f</a>, 21; 9:7, 8b (oposto a <span class=\"greek\">σπέρμα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a>, v. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:1</a>; em João como os que foram gerados por Deus J 1:12; 11:52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:1f</a>, 10a; 5:2. Correspondentemente <span class=\"greek\">τὰ</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:10b</a> (sobre este assunto v. Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44</a>).—Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:28</a>, onde a ideia de parentesco com a divindade é complexa por causa de componentes semânticos não compartilhados pelos politeístas e por aqueles inseridos na tradição israelita.—Cf. 6 abaixo.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> habitantes de uma cidade, filhos, expressão hebraística (Rdm.2 p. 28; Mlt-H. 441; v. Jo 2:23; Zech 9:13; Bar 4:19, 21, 25 al.; 1 Macc 1:38; PsSol 11:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; 19:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:25</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">⑥</span> classe de pessoas com determinada característica, filhos de. <span class=\"greek\">τ</span>. é empregado com termos abstratos (sobre este hebraísmo v. acima; <span class=\"greek\">ἀνάγκης</span>, <span class=\"greek\">ἀγνοίας</span> Just., A I, 61, 10) <span class=\"greek\">τέκνα</span> <span class=\"greek\">ἀγάπης</span> B 9:7; <span class=\"greek\">ἀγ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνης</span> 21:9 (<span class=\"greek\">ἀγάπη</span> 1b<span class=\"greek\">α</span>). <span class=\"greek\">εὐφροσύνης</span> 7:1 (v. <span class=\"greek\">εὐφροσύνη</span>). <span class=\"greek\">δικαιοσύνης</span> AcPlCor 2:19. <span class=\"greek\">κατάρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:14</a> (v. <span class=\"greek\">κατάρα</span>). <span class=\"greek\">ὀργῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>; AcPlCor 2:19. <span class=\"greek\">ὑπακοῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:14</a>. <span class=\"greek\">φωτός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:8</a>; cf. IPhld 2:1. Sobre os ‘filhos da sabedoria’, isto é, aqueles que a ela se apegam e se deixam conduzir por ela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:19</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:35</a> v. <span class=\"greek\">δικαιόω</span> 2b<span class=\"greek\">α</span>. Cf. 4b acima.—Billerbeck I 219f, 371–74; BHHW II 947–49; III 1935–37.—DELG s.v. <span class=\"greek\">τίκτω</span>. Frisk. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνοτροφέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκνοτροφέω</span> 1 aor. <span class=\"greek\">ἐτεκνοτρόφησα</span> (desde Aristot., HA 9, 40, 14, 625b, 20 [da abelha]; IG XII, 5, 655, 8 [II/III d.C.]; SEG XXVII, 948a, 5f [crist. VI d.C.) criar filhos, isto é, cuidar deles física e espiritualmente (Epict. 1, 23, 3 seguindo Epicurus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:10</a>.—New Docs 2, 194. DELG s.v. <span class=\"greek\">τρέφω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεκνόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεκνόω</span> 1 aor. <span class=\"greek\">ἐτέκνωσα</span> (Just.); aor. pass. subj. <span class=\"greek\">τεκνωθῶ</span> Gen 16:2 Sym. (Hes., Fgm. 138 R.; Trag.; Phalaris, Ep. 103, 2) comumente do homem no sentido de ‘gerar’ (ISmyrna I [IK 23] 541, 4; Plut., Pericl. 165 [24, 10]; En 15:5; Jos., Ant. 1, 150; 2, 213; Just.), mas também, e somente assim em nossa lit., da mulher, dar à luz (uma criança) (Jos., Ant. 4, 255) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a> v.l.—DELG s.v. <span class=\"greek\">τίκτω</span> A. Frisk s.v. <span class=\"greek\">τέκνον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέκτων, ονος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέκτων</span>, <span class=\"greek\">ονος</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">τέχνη</span>; Hom. et al.; pap., LXX; Jos., Ant. 15, 390; SibOr 5, 404; Ath., R. 9 p. 57, 28) aquele que constrói, construtor, carpinteiro (Hom.+; SEG XXVIII, 1186 ‘trabalhador em madeira, carpinteiro, marceneiro’. Segundo Maximus Tyr. 15, 3c, um <span class=\"greek\">τ</span>. fabrica <span class=\"greek\">ἄροτρα</span>; Just. , D. 88, 8, afirma que José fabricava <span class=\"greek\">ἄροτρα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζυγά</span> ‘arados e jugos’; segundo Epict. 1, 15, 2 um <span class=\"greek\">τ</span>. trabalha com madeira, em contraste com um trabalhador em bronze; para este último, menos frequentemente, Eur., Alc. 5; em Ael. Aristid. 46 p. 211 D. <span class=\"greek\">τέκτων</span> significa trabalhador em pedra. GJs 9:3 al. o trabalho de José é <span class=\"greek\">οἰκοδομῆσαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκοδομάς</span>; a palavra. <span class=\"greek\">τ</span>. não é empregada.—CMcCown, <span class=\"greek\">ὁ</span> <span class=\"greek\">τέκτων</span>: Studies in Early Christ., ed. SCase 1928, 173–89). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:55</a> Jesus é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τέκτονος</span> <span class=\"greek\">υἱός</span>, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a> <span class=\"greek\">ὁ</span> <span class=\"greek\">τέκτων</span> (cf. Just., D. 88, 8=ASyn. 18, 55f; a diferença talvez possa ser explicada com base em outra semelhante relativa a Sófilo, pai de Sófocles: Aristoxenus, Fgm. 115 chama-o <span class=\"greek\">τέκτων</span>, mas a Vita Sophoclis 1 [=OxfT. of Soph., ed. Pearson p. xviii; não impressa na ed. de NWilson ’90] rejeita isso e admite somente que ele talvez tenha possuído <span class=\"greek\">τέκτονες</span> como escravos. Considerações de posição social podem ter alguma relação com a variação na tradição evangélica).—HHöpfl, Nonne hic est fabri filius?: Biblica 4, 1923, 41–55; ELombard, Charpentier ou maçon: RTP ’48, 4; EStauffer, Jeschua ben Mirjam (Mk 6:3): MBlack Festschr., ’69, 119–28; RBatey, NTS 30, ’84, 249–58.—B. 589. BHHW III 2341. DELG. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέλειος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέλειος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hom. [p. ex. Il. 24, 34 de animais sacrificiais sem defeito] +) geralmente ‘que atinge um fim ou propósito, completo’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a satisfazer o mais elevado padrão</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de coisas, perfeito</p><p class=\"entry-text\"><span class=\"greek\">α</span>. como ápice da bondade, como adj. (<span class=\"greek\">ἀρετή</span> Did., Gen. 40, 19.—De éons, Iren. 1, 1, 1 [Harv. I 8, 2]; Hippol., Ref. 6, 31, 4) <span class=\"greek\">ἔργον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:4a</a> (v. <span class=\"greek\">ἔργον</span> lb); cf. ISm 11:2. <span class=\"greek\">δώρημα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a> (v. <span class=\"greek\">δώρημα</span>). <span class=\"greek\">νόμος</span> v. 25 (oposto à lei mosaica). <span class=\"greek\">ἀγάπη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:18</a>. <span class=\"greek\">ἀνάλυσις</span> 1 Cl 44:5 (Just., D. 41, 1). <span class=\"greek\">γνῶσις</span> 1:2; B 1:5. <span class=\"greek\">πρόγνωσις</span> 1 Cl 44:2. <span class=\"greek\">μνεία</span> 56:1. <span class=\"greek\">ἐλπίς</span> ISm 10:2 (v.l. <span class=\"greek\">πίστις</span>); <span class=\"greek\">χάρις</span> 11:1. <span class=\"greek\">νηστεία</span> Hs 5, 3, 6. <span class=\"greek\">ναός</span> B 4:11 (<span class=\"greek\">ἐκκλησία</span> Did., Gen. 69, 14). <span class=\"greek\">τελειοτέρα</span> <span class=\"greek\">σκηνή</span> (v. <span class=\"greek\">σκηνή</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:11</a>.—Subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλειον</span> aquilo que é perfeito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:2</a>; talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:10</a> (oposto a <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέρους</span>. V. EHoffmann, ConNeot 3, ’38, 28–31). <span class=\"greek\">ἐνάρετον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέλειον</span> (algo) virtuoso e perfeito IPhld 1:2. Com gen. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλειον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">ἡμῶν</span> a plena medida de nosso conhecimento B 13:7. Pl. (Philo) <span class=\"greek\">τέλεια</span> aquilo que é perfeito ISm 11:3b (Tat. 13, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">τέλεια</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. como ápice da maldade (ApcSed 14:7 <span class=\"greek\">ἀπόγνωστοι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τελείαν</span> <span class=\"greek\">ἀπόγνωσιν</span>), adj. <span class=\"greek\">ἁμαρτίαι</span> B 8:1; Hv 1, 2, 1. <span class=\"greek\">σκάνδαλον</span> B 4:3.—Subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλειον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> a plena medida dos pecados 5:11.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de pessoas que satisfazem plenamente o padrão em determinado aspecto e não se contentam com meias medidas, perfeito, completo, perito (TAM II/1, 147, 4f <span class=\"greek\">ἰατρὸς</span> <span class=\"greek\">τέλειος</span>; ZPE 3, ’68, 86: Didymus Fgm. 281, 7 <span class=\"greek\">τέλειος</span> <span class=\"greek\">γεώμετρος</span>; Wsd 9:6; 1 Ch 25:8) <span class=\"greek\">τέλειος</span> <span class=\"greek\">ἀθλητής</span> IPol 1:3. Ester é <span class=\"greek\">τελεία</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πίστιν</span> 1 Cl 55:6. Jesus tornou-se <span class=\"greek\">τέλειος</span> <span class=\"greek\">ἄνθρωπος</span> ser humano perfeito ISm 4:2.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a ser maduro, plenamente desenvolvido, maduro, adulto (Aeschyl., Pla., X.+; frequentemente pap.; Philo; Jos., Ant. 19, 362).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> adj. <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">τέλειος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a> (oposto a <span class=\"greek\">νήπιοι</span>, como Polyb. 5, 29, 2; Philo, Leg. All. 1, 94, Sobr. 9 <span class=\"greek\">νήπιον</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">τέλειον</span>=uma criança imatura comparada a um homem maduro, Somn. 2, 10). Em brilhante jogo de palavras: <span class=\"greek\">μὴ</span> <span class=\"greek\">παιδία</span> <span class=\"greek\">γίνεσθε</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">φρεσίν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κακίᾳ</span> <span class=\"greek\">νηπιάζετε</span>, <span class=\"greek\">ταῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">φρεσὶν</span> <span class=\"greek\">τέλειοι</span> <span class=\"greek\">γίνεσθε</span> não penseis como crianças, mas sede crianças de peito quanto ao mal, sendo, ao mesmo tempo, adultos em vosso pensamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:20</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> subst. (Dio Chrys. 34 [51], 8 <span class=\"greek\">οἱ</span> <span class=\"greek\">τ</span>.; Diogenes, Ep. 31, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">τ</span>. … <span class=\"greek\">οἱ</span> <span class=\"greek\">παῖδες</span>; Ath., R. 17 p. 68, 31) <span class=\"greek\">τελείων</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">στερεὰ</span> <span class=\"greek\">τροφή</span> o alimento sólido é (somente) para adultos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:14</a> (oposto a <span class=\"greek\">νήπιος</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">τέλειοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:6</a> é contraposto a <span class=\"greek\">νήπιοι</span> 3:1 por WBauer, Mündige u. Unmündige bei dem Ap. Paulus, diss. Marburg 1902 (também Aufsätze u. Kleine Schriften, ed. GStrecker, ’67, 124–30 et al.; v. também GDelling, TW VIII 76–78.) Mas isto também pode pertencer à classificação seguinte</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> relativo a ser iniciado num culto, iniciado. Como t.t. das religiões de mistérios, <span class=\"greek\">τέλειος</span> refere-se a quem foi iniciado em ritos místicos (<span class=\"greek\">τελετή</span>; v. <span class=\"greek\">τελειόω</span> 3; cf. Herm. Wr. 4, 4; Philod., <span class=\"greek\">Περὶ</span> <span class=\"greek\">θεῶν</span> 1, 24, 12 [ed. HDiels, ABA 1915 p. 41; 93]; Iambl., Myst. 3, 7 p. 114 Parthey; Philo, Somn. 2, 234; gnósticos [WBousset, Kyrios Christos2 1921 p. 197, 1].—Rtzst., Mysterienrel.3 133f; 338f; JWeiss, exc. após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:3</a>, também p. xviiif, Das Urchristentum 1917, 492; HKennedy, St. Paul and the Mystery Religions 1913, 130ff; Clemen2 314; em geral, CZijerveld, <span class=\"greek\">Τελετή</span>, Bijdrage tot de kennis der religieuze terminologie in het Grieksch ’34). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:15</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:28</a> provavelmente pertencem aqui (v. MDibelius, Hdb. sobre ambas as passagens. <span class=\"greek\">οἱ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χριστιανισμῷ</span> <span class=\"greek\">τ</span>. Orig., C. Cels. 3, 19, 13).—CGuignebert, Quelques remarques sur la Perfection (<span class=\"greek\">τελείωσις</span>) et ses voies dans le mystère paulinien: RHPR 8, 1928, 412–29; UWilckens, Weisheit u. Torheit, ’59, 53–60 apoia Reitzenstein contra Bauer.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> relativo a ser plenamente desenvolvido em sentido moral</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de seres humanos, perfeito, plenamente desenvolvido (Hippol., Ref. 1, 19, 16) em sentido moral <span class=\"greek\">τέλειος</span> <span class=\"greek\">ἀνήρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:2</a> (v. RHöistad, ConNeot 9, ’44, p. 22f). <span class=\"greek\">τὸν</span> <span class=\"greek\">τέλειον</span> <span class=\"greek\">ἄνθρωπον</span> GMary 463, 26f (restaurado). Geralmente sem substantivo <span class=\"greek\">εἰ</span> <span class=\"greek\">θέλεις</span> <span class=\"greek\">τέλειος</span> <span class=\"greek\">εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:21</a> (EYarnold, TU 102, ’68, 269–73). Cf. IEph 15:2; D 1:4; 6:2. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:48a</a>; ISm 11:3a. Com <span class=\"greek\">ὁλόκληροι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:4b</a>. Com <span class=\"greek\">πεπληροφορημένοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de Deus, perfeito (Pind., Aeschyl. et al.; Theocr., Diod S, Plut. et al.; Tat.4, 2, 12; 4, 15, 2; Theoph. Ant. 2, 15 [p. 138, 12]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:48b</a> (isto é, Deus é um modelo para a manifestação ilimitada de beneficência; cf. sobre este versículo Hierocles 18 p. 459: o objetivo é <span class=\"greek\">τὴν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὁμοίωσιν</span> <span class=\"greek\">κτήσασθαι</span> ‘obtenção da semelhança com Deus’ [frequentemente em Hierocles]; Marinus, Vi. Procli 18 <span class=\"greek\">ἵνα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁμοίωσιν</span> <span class=\"greek\">ἔχῃ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, <span class=\"greek\">ὅπερ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄριστον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>; Betz, SM ad loc.). Restauração num contexto corrompido AcPl Ha 1, 11 (o ed. indica <span class=\"greek\">τελέσαι</span> ou <span class=\"greek\">τελεῖν</span> como alternativas).—RFlew, The Idea of Perfection ’34; FGrant, The Earliest Gospel, ’43; EFuchs, RBultmann Festschr., ’54 (Beih. ZNW 21), 130–36; PDuPlessis, Teleios. The Idea of Perfection in the NT ’59; KPrümm, Das NTliche Sprach-u. Begriffsproblem der Vollkommenheit, Biblica 44, ’63, 76–92; AWikgren, Patterns of Perfection in Hb, NTS 6, ’60, 159–67.—Schmidt, Syn. IV 503f. DELG s.v. <span class=\"greek\">τέλος</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελειότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελειότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τέλειος</span>) perfeição, plenitude (Ps.-Pla., Def. 412b; Epict. 1, 4, 4; M. Ant. 5, 15, 2; PGM 7, 778; Wsd 6:15; 12:17; Philo; Iren. 1, 7, 5 [Harv. I 65, 7]) do amor em sua perfeição 1 Cl 50:1; 53:5. Da maturidade em contraste com o estágio do conhecimento elementar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>.—Sobre <span class=\"greek\">σύνδεσμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τελειότητος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:14</a> v. <span class=\"greek\">σύνδεσμος</span> 2.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελειόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελειόω</span> (<span class=\"greek\">τέλειος</span>) fut. <span class=\"greek\">τελειώσω</span>; 1 aor. <span class=\"greek\">ἐτελείωσα</span>; perf. <span class=\"greek\">τετελείωκα</span>. Pass.: perf. <span class=\"greek\">τετελείωμαι</span>; 1 fut. <span class=\"greek\">τελειωθήσομαι</span>; 1 aor. <span class=\"greek\">ἐτελειώθην</span>; perf. <span class=\"greek\">τετελείωμαι</span> (Soph., Hdt.+; inscr., pap., LXX; TestAbr A 15 p. 95, 7 [Stone p. 38]; TestGad 7:1; EpArist, Philo; Jos., Vi. 12 al.; Ath., R. 17 p. 69, 10. A forma <span class=\"greek\">τελεόω</span>, frequentemente empregada fora de nossa lit., ocorre somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:1</a> v.l.—B-D-F §30, 2; Thackeray p. 82).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> completar uma atividade, completar, levar a termo, terminar, realizar (Dionys. Hal. 3, 69, 2 <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκοδομῆς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">εἰργάσατο</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴν</span> <span class=\"greek\">ἐτελείωσε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>; Polyb. 8, 36, 2; 2 Ch 8:16; 2 Esdr 16: 3, 16) <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:34</a>; 17:4; pl. 5:36. <span class=\"greek\">πάντα</span> 1 Cl 33:6. <span class=\"greek\">ὡς</span> <span class=\"greek\">τελειώσω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δρόμον</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:24</a>. <span class=\"greek\">ἁγνῶς</span> <span class=\"greek\">τελειοῦν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> cumprir em santidade o serviço de diácono Hs 9, 26, 2. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span> passar todos os dias da festa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:43</a> (cf. Jos., Ant. 3, 201). Pass. <span class=\"greek\">ἵνα</span> <span class=\"greek\">τελειωθῇ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γραφή</span> a fim de que a Escritura recebesse seu cumprimento definitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:28</a> (talvez isto pertença a 2c.)—<span class=\"greek\">τελειῶσαί</span> <span class=\"greek\">τινα</span> permitir que alguém alcance seu objetivo (Hdt. 3, 86) pass. <span class=\"greek\">τῇ</span> <span class=\"greek\">τρίτῃ</span> <span class=\"greek\">τελειοῦμαι</span> ao terceiro dia alcançarei meu objetivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:32</a> (dificilmente médio, ‘levar a termo’ [Iambl., Vi. Pyth. 158] com ‘minha obra’ a ser suprido. Mas v. 2d abaixo e cf. JDerrett, ZNW 75, ’84, 36–43 [jogo de palavras envolvendo a morte]).—Este talvez seja também o lugar de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:19</a> (v. 2e<span class=\"greek\">α</span> abaixo); 11:40 (v. 2d abaixo).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> superar ou suplantar um estado imperfeito de coisas por outro isento de objeções, levar a termo, levar a seu objetivo/consumação</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de Jesus <span class=\"greek\">ἔπρεπεν</span> <span class=\"greek\">αὐτῷ</span> (isto é, <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>) <span class=\"greek\">διὰ</span> <span class=\"greek\">παθημάτων</span> <span class=\"greek\">τελειῶσαι</span> (<span class=\"greek\">Ἰησοῦν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a> (isto é, como indica o contexto, ele recebe as mais elevadas honras mediante sofrimento e morte em sua identificação com a humanidade); pass., 5:9; 7:28. Entende-se geralmente que isto significa a consumação e o aperfeiçoamento de Jesus pela superação das limitações terrenas (v. Windisch, Hdb. exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:9</a>.—JKögel, Der Begriff <span class=\"greek\">τελειοῦν</span> im Hb: MKähler Festschr. 1905, 35–68; OMichel, D. Lehre von d. christl. Vollkommenheit nach d. Anschauung des Hb: StKr 106, ’35, 333–55; FTorm, Om <span class=\"greek\">τελειοῦν</span> i Hb: Sv. Ex. Årsb. 5, ’40, 116–25; OMoe, TZ 5, ’49, 165ff). V. 3 abaixo.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> levar à plena medida, encher a medida de <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀποκαλύψεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὁράματα</span> Hv 4, 1, 3. <span class=\"greek\">ἐτελείωσαν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἁμαρτήματα</span> GPt 5:17 (<span class=\"greek\">κατά</span> A 2b<span class=\"greek\">γ</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> cumprir, de profecias, promessas etc., que suscitam a expectativa de acontecimentos ou ocorrências que correspondam à sua formulação (<span class=\"greek\">τελείωσις</span> 2.—Jos., Ant. 15, 4 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τελειώσαντος</span>; Artem. 4, 47 p. 228, 19 <span class=\"greek\">ἐλπίδας</span>) <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐπαγγέλλεται</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">τελειοῖ</span> Hm 9:10; pass. cumprir-se <span class=\"greek\">ἐξαίφνης</span> <span class=\"greek\">τελειωθήσεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βούλημα</span> <span class=\"greek\">αὐτοῦ</span> 1 Cl 23:5.—MPol 16:2ab. As promessas dos profetas encontram seu cumprimento, por implicação, no evangelho ISm 7:2. Este talvez seja o lugar de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:28</a> (assim Bultmann.—V. 1 acima).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> do aperfeiçoamento de pessoas justas que nos precederam, pass. (Wsd 4:13; Philo, Leg. All. 3, 74 <span class=\"greek\">ὅταν</span> <span class=\"greek\">τελειωθῇς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βραβείων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">στεφάνων</span> <span class=\"greek\">ἀξιωθῇς</span>) <span class=\"greek\">πνεύματα</span> <span class=\"greek\">δικαίων</span> <span class=\"greek\">τετελειωμένων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:23</a>. Assim talvez também 11:40 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:32</a> (v. 1 acima).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓔ</span> tornar perfeito</p><p class=\"entry-text\"><span class=\"greek\">α</span>. alguém <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προσερχομένους</span> <span class=\"greek\">τελειῶσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:1</a>; igualmente talvez (v. 1 acima) 7:19 (então <span class=\"greek\">οὐδέν</span> se referiria à humanidade). <span class=\"greek\">κατὰ</span> <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">τελειῶσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λατρεύοντα</span> 9:9. Talvez 10:14 (v. 3 abaixo). Pass. em sentido ativo tornar-se perfeito (Zosimus: Hermet. IV p. 111, 15f ) D 16:2; <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> em algo (Jos., Ant. 16, 6) <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">ἀγάπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:18</a>; 1 Cl 49:5; 50:3. Com inf. subsequente B 6:19. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὦσιν</span> <span class=\"greek\">τετελειωμένοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕν</span> a fim de que alcancem perfeita unidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:23</a>.—Também em sentido desfavorável <span class=\"greek\">τελειωθῆναι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁμαρτήμασιν</span> B 14:5.—Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a> v. 3 abaixo.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. algo. Invoca-se o Senhor, em benefício de sua comunidade, <span class=\"greek\">τελειῶσαι</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">σου</span> D 10:5. Pass. (Philo, Somn. 1, 131 <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">τελειωθεῖσα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἄθλοις</span> <span class=\"greek\">ἀρετῶν</span>) <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ἐτελειώθη</span> a fé foi aperfeiçoada nas boas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:22</a>. Do amor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:5</a>; 4:12, 17. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:9</a> v.l.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> Como termo das religiões de mistérios, consagrar, iniciar, pass. ser consagrado, tornar-se um <span class=\"greek\">τέλειος</span> (v. <span class=\"greek\">τέλειος</span> 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a> (embora a acepção 2e<span class=\"greek\">α</span> também seja provável). Algumas das passagens de Hb (v. 2a; e<span class=\"greek\">α</span> acima) talvez pertençam aqui, esp. aquelas em que se menciona uma consagração de Jesus 2:10; 5:9; 7:28 (v. THaering, Monatschr. für Pastoraltheol. 17, 1921, 264–75. Contra ele ERiggenbach, NKZ 34, 1923, 184–95 e Haering mais uma vez, ibid. 386–89.—EKaesemann, D. wand. Gottesvolk ’39, 82–90; GAvdBerghvEysinga, De Brief aan de Hebreën en de oudchristelijke Gnosis: NThT 28, ’39, 301–30).—DELG s.v. <span class=\"greek\">τέλος</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελείως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελείως</span> adv. de <span class=\"greek\">τέλειος</span> (esta forma em Isocr. 13, 18; Ps.-Pla., Def. 411d; Aristot. et al.; Polyb. 6, 24, 7; Hero Alex. I p. 20, 25; PPetr III, 42 H 8c, 3 p. 114 [III a.C.]; PFlor 93, 27; LXX [Thackeray p. 82]; TestSol 26, 7 B e 8 B; TestAbr B 7 p. 112, 5 [Stone p. 72]; TestGad 7:1; Philo; Ath. 26:2 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τελείως</span> <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">ὤν</span>) plenamente, perfeitamente, completamente, inteiramente <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> IEph 14:1. <span class=\"greek\">ἐλπίζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:13</a>. De serviço dedicado <span class=\"greek\">τ</span>. <span class=\"greek\">λειτουργεῖν</span> desempenhar excelentemente 1 Cl 9:2. <span class=\"greek\">φεύγειν</span> B 4:1. <span class=\"greek\">μισεῖν</span> <span class=\"greek\">τι</span> 4:10. <span class=\"greek\">φανεροῦσθαι</span> Dg 9:2. <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀπαρτίζειν</span> IEph 1:1. <span class=\"greek\">ἀπαρνεῖσθαι</span> ISm 5:2. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τελείως</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> ter recebido plena iluminação acerca de algo.—B 10:10.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελείωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελείωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τελειόω</span>; desde Hippocr. VII 436; 448 L.; Epicurus p. 38, 5 Us.; Aristot.; inscr., pap., LXX, En; TestAbr A 20 p. 103, 24 [Stone p. 54]; TestReub 6:8; EpArist; Philo, Aet. M. 71; 99; Jos., Ant. 19, 199 em sentido diferente; Ar. [Milne 76, 48]; Ath., R. 17 p. 69, 9)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> perfeição (En 25, 4; Ar., Ath.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> cumprimento de uma promessa (Jdth 10:9; Philo, Mos. 2, 288.—<span class=\"greek\">τελειόω</span> 2c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:45</a>.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελειωτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελειωτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τελειόω</span>; Dionys. Hal., Dinarchus 1; de resto somente em escritos crist. Methodius MPG XVIII, 360b; sobre a morfologia Schwyzer I 500) aquele que leva algo a uma conclusão bem-sucedida, consumador (oposto a <span class=\"greek\">ἀρχηγός</span>, q.v. 3; Jesus é ambos) <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a> (AWikgren, NTS 6, ’60, 159–67; NCroy, JBL 114, ’95, 117–19=‘aquele que não há de ser superado por aperfeiçoamentos subsequentes’).—DELG s.v. <span class=\"greek\">τέλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέλεον</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέλεον</span> acus. sing. neut. de <span class=\"greek\">τέλεος</span> (=<span class=\"greek\">τέλειος</span>; cf. SibOr 3, 117) empregado como adv. (<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 41, 1; Ael. Aristid. 33 p. 635 D.; Lucian, Merc. Cond. 5; Appian, Bell. Civ. 1, 8 §34; BGU 903, 12 [II d.C.]; PFay 106, 21; 3 Macc 1:22; JosAs. 12:11 cod. A [p. 56, 14 Bat.]; Jos., Bell. 4, 285) relativo a estar no fim de um processo, plenamente, inteiramente, no fim Dg 2:5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελεσφορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελεσφορέω</span> (<span class=\"greek\">τέλος</span>, <span class=\"greek\">φέρω</span>; Theophr. et al.; 4 Macc 13:20; Philo; Jos., Ant. 1, 140) produzir fruto até a maturidade (Jülicher, Gleichn. 530.—Cf. Ocellus Luc. [II a.C.] c. 16 Harder [1926]; Epict. 4, 8, 36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14</a>, 15 v.l.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελευταῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελευταῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Aeschyl., Hdt. +) relativo ao encerramento de uma série, final, último, como ponto conclusivo no tempo <span class=\"greek\">τελευταία</span> <span class=\"greek\">ἡμέρα</span> (Demosth. et al.; Epict. 2, 23, 21; IG IV2 1, 123, 128 [IV a.C.] <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">τελευταίαις</span> <span class=\"greek\">ἁμέραις</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span> GPt 14:58.—Schmidt, Syn. IV 524–34, cf. <span class=\"greek\">ἔσχατος</span>. DELG s.v. <span class=\"greek\">τέλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0355-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελευτάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελευτάω</span> (<span class=\"greek\">τελευτή</span>; Hom. et al.) fut. <span class=\"greek\">τελευτήσω</span>; 1 aor. <span class=\"greek\">ἐτελεύτησα</span>; perf. 3 sg. <span class=\"greek\">τετελεύτηκεν</span> Josh 1:2, ptc. <span class=\"greek\">τετελευτηκώς</span>; em nossa lit. somente intr.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> chegar ao fim (Aeschyl. et al.) Papias (4), v. <span class=\"greek\">συμβαίνω</span> 2.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> morrer (Aeschyl., Hdt. et al.—B-D-F §480, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:19</a> (cf. GJs 25:1); 9:18; 22:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:29</a>; 7:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a>; 1 Cl 39:6 (Job 4:21 v.l.); Papias (3:3). Da fênix 1 Cl 25:2f. Como em Is 66:24, do verme no inferno: Mk 9:43 (44) e 45 (46) ambos v.l.; 48; 2 Cl 7:6; 17:5. <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">τελευτάτω</span> morra a pessoa de morte = certamente morrer (=<span class=\"hebrew\" dir=\"rtl\">מוֹת</span> <span class=\"hebrew\" dir=\"rtl\">יוּמָת</span> Ex 21:17 Mt; JosAs cod. A cap. 21 [p. 71, 28 Bat., também Pal. 364]. Mas v. também schol. sobre Soph., Ajax 516 p. 46 <span class=\"greek\">τελευτᾶν</span> <span class=\"greek\">θανάτῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:4</a> (cf. Ex 21:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:10</a>.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M.</p></section></article>"};
